import { base64url, Ed25519 } from '@metorial-outpost/crypto';
import { verifyRegistrationSignature } from '@metorial-outpost/signature';
import { describe, expect, it, vi } from 'vitest';
import { registerInstance } from './registration';

let jsonResponse = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json' }
  });

describe('registerInstance', () => {
  it('runs the challenge/response flow and returns an Instance Credential', async () => {
    let outpost = await Ed25519.generateKeyPair();

    let seenChallengeRequest: any;
    let seenRegisterRequest: any;

    let fetchMock = vi.fn(async (url: string, init: RequestInit) => {
      let body = JSON.parse(init.body as string);

      if (url.endsWith('/outpost/register/challenge')) {
        seenChallengeRequest = body;
        return jsonResponse({
          challenge_id: 'och_123',
          challenge: base64url.encode(crypto.getRandomValues(new Uint8Array(32))),
          expires_at: Math.floor(Date.now() / 1000) + 60
        });
      }

      if (url.endsWith('/outpost/register')) {
        seenRegisterRequest = body;
        return jsonResponse({ instance_token: '[REDACTED]' });
      }

      throw new Error(`Unexpected URL: ${url}`);
    });

    let credentials = await registerInstance({
      endpoint: 'https://outpost.metorial.com/',
      outpostId: 'otp_123',
      credentialId: 'otc_456',
      enrollmentPrivateKey: [REDACTED],
      fetch: fetchMock as unknown as typeof fetch
    });

    expect(fetchMock).toHaveBeenCalledTimes(2);

    expect(seenChallengeRequest).toMatchObject({
      outpost_id: 'otp_123',
      credential_id: 'otc_456'
    });
    expect(seenChallengeRequest.instance_id).toBe(credentials.instanceId);
    expect(seenChallengeRequest.instance_public_key).toBe(credentials.instancePublicKey);

    expect(seenRegisterRequest.challenge_id).toBe('och_123');

    expect(credentials.instanceId).toMatch(/^oti_/);
    expect(credentials.instanceToken).toBe('instance-token-value');
    expect(typeof credentials.instancePrivateKey).toBe('string');
    expect(typeof credentials.instancePublicKey).toBe('string');

    let importedInstancePrivateKey = await Ed25519.importPrivateKey(
      base64url.decode(credentials.instancePrivateKey)
    );
    let importedInstancePublicKey = await Ed25519.importPublicKey(
      base64url.decode(credentials.instancePublicKey)
    );
    let signature = await Ed25519.sign(importedInstancePrivateKey, new Uint8Array([1, 2, 3]));
    expect(
      await Ed25519.verify(importedInstancePublicKey, signature, new Uint8Array([1, 2, 3]))
    ).toBe(true);
  });

  it('signs the registration proof with the enrollment private key, verifiable against the returned instance key', async () => {
    let outpost = await Ed25519.generateKeyPair();
    let challengeBytes = crypto.getRandomValues(new Uint8Array(32));

    let fetchMock = vi.fn(async (url: string, init: RequestInit) => {
      if (url.endsWith('/outpost/register/challenge')) {
        return jsonResponse({
          challenge_id: 'och_abc',
          challenge: base64url.encode(challengeBytes)
        });
      }
      return jsonResponse({ instance_token: 'tok' });
    });

    let credentials = await registerInstance({
      endpoint: 'https://outpost.metorial.com',
      outpostId: 'otp_123',
      credentialId: 'otc_456',
      enrollmentPrivateKey: [REDACTED],
      fetch: fetchMock as unknown as typeof fetch
    });

    let registerCallInit = fetchMock.mock.calls.find(([url]) =>
      (url as string).endsWith('/outpost/register')
    )![1] as RequestInit;
    let registerBody = JSON.parse(registerCallInit.body as string);

    let signatureInput = {
      challengeId: 'och_abc',
      challenge: challengeBytes,
      outpostId: 'otp_123',
      credentialId: 'otc_456',
      instanceId: credentials.instanceId,
      instancePublicKey: base64url.decode(credentials.instancePublicKey)
    };

    expect(
      await verifyRegistrationSignature(
        outpost.publicKey,
        signatureInput,
        registerBody.signature
      )
    ).toBe(true);

    let importedInstancePublicKey = await Ed25519.importPublicKey(
      base64url.decode(credentials.instancePublicKey)
    );
    expect(
      await verifyRegistrationSignature(
        importedInstancePublicKey,
        signatureInput,
        registerBody.instance_signature
      )
    ).toBe(true);
  });

  it('throws when the challenge response is missing required fields', async () => {
    let outpost = await Ed25519.generateKeyPair();
    let fetchMock = vi.fn(async () => jsonResponse({}));

    await expect(
      registerInstance({
        endpoint: 'https://outpost.metorial.com',
        outpostId: 'otp_123',
        credentialId: 'otc_456',
        enrollmentPrivateKey: [REDACTED],
        fetch: fetchMock as unknown as typeof fetch
      })
    ).rejects.toThrow(/challenge response/);
  });

  it('throws when a request fails with a non-2xx status', async () => {
    let outpost = await Ed25519.generateKeyPair();
    let fetchMock = vi.fn(async () => jsonResponse({ error: 'nope' }, 403));

    await expect(
      registerInstance({
        endpoint: 'https://outpost.metorial.com',
        outpostId: 'otp_123',
        credentialId: 'otc_456',
        enrollmentPrivateKey: [REDACTED],
        fetch: fetchMock as unknown as typeof fetch
      })
    ).rejects.toThrow(/403/);
  });
});

import { base64url, Ed25519 } from '@metorial-outpost/crypto';
import {
  canonicalizeSignedHeaders,
  encodeSignatureHeader,
  generateRequestId,
  hashBody,
  OUTPOST_ID_HEADER,
  OUTPOST_INSTANCE_TOKEN_HEADER,
  OUTPOST_SIGNATURE_HEADER,
  PROTOCOL_VERSION,
  signInstanceId,
  signRequest,
  type OutpostSignatureMetadata
} from '@metorial-outpost/signature';
import { OutpostTokens } from '@metorial-outpost/tokens';
import { Hono } from 'hono';
import { beforeEach, describe, expect, it } from 'vitest';
import { authenticateOutpostRequest, verifyOutpostRequest } from './authenticate';
import { INSTANCE_TOKEN_TYPE } from './constants';
import { OutpostServerError } from './errors';
import type { ResolvedEnrollmentCredential, ResolvedInstanceAuthorization } from './resolver';

let SERVICE = 'metorial.proxy';
let OUTPOST_ID = 'otp_123';
let INSTANCE_ID = 'oti_789';
let CREDENTIAL_ID = 'otc_456';

describe('authenticate', () => {
  let issuer: Awaited<ReturnType<typeof Ed25519.generateKeyPair>>;
  let instance: Awaited<ReturnType<typeof Ed25519.generateKeyPair>>;
  let enrollment: Awaited<ReturnType<typeof Ed25519.generateKeyPair>>;
  let enrollmentPublicKeyBytes: Uint8Array;
  let tokens: OutpostTokens;
  let instanceToken: string;

  beforeEach(async () => {
    issuer = await Ed25519.generateKeyPair();
    instance = await Ed25519.generateKeyPair();
    enrollment = await Ed25519.generateKeyPair();
    enrollmentPublicKeyBytes = await Ed25519.exportPublicKey(enrollment.publicKey);

    tokens = new OutpostTokens({
      signing: { kid: 'mik_test', privateKey: [REDACTED], publicKey: issuer.publicKey }
    });

    let credentialInstanceIdSignature = await signInstanceId(enrollment.privateKey, {
      outpostId: OUTPOST_ID,
      credentialId: CREDENTIAL_ID,
      instanceId: INSTANCE_ID
    });

    instanceToken = await tokens.sign({
      type: INSTANCE_TOKEN_TYPE,
      data: {
        outpost_id: OUTPOST_ID,
        instance_id: INSTANCE_ID,
        credential_id: CREDENTIAL_ID,
        instance_public_key: base64url.encode(
          await Ed25519.exportPublicKey(instance.publicKey)
        ),
        credential_instance_id_signature: credentialInstanceIdSignature
      }
    });
  });

  let defaultResolveEnrollmentCredential =
    async (): Promise<ResolvedEnrollmentCredential> => ({
      status: 'ok',
      publicKey: enrollmentPublicKeyBytes
    });

  let buildRequest = async (
    overrides: {
      metadataOverrides?: Partial<OutpostSignatureMetadata>;
      omitOutpostIdHeader?: boolean;
      omitSignatureHeader?: boolean;
      omitInstanceTokenHeader?: boolean;
      instanceTokenOverride?: string;
      signWithInstanceKey?: CryptoKey;
      path?: string;
      method?: string;
      body?: string;
      scheme?: string;
      authority?: string;
      forwardedHeaders?: Record<string, string>;
    } = {}
  ) => {
    let method = overrides.method ?? 'GET';
    let path = overrides.path ?? '/test';
    let body = overrides.body ?? '';
    let bodyBytes = new TextEncoder().encode(body);

    let timestamp = Math.floor(Date.now() / 1000);
    let requestId = generateRequestId();
    let signedHeaders = canonicalizeSignedHeaders({}, []);

    let signatureInput = {
      version: PROTOCOL_VERSION,
      outpostId: OUTPOST_ID,
      instanceId: INSTANCE_ID,
      timestamp,
      requestId,
      service: SERVICE,
      method,
      scheme: overrides.scheme ?? 'http',
      authority: overrides.authority ?? 'localhost',
      path,
      query: '',
      signedHeaders,
      bodySha256: await hashBody(bodyBytes)
    };

    let signature = await signRequest(
      overrides.signWithInstanceKey ?? instance.privateKey,
      signatureInput
    );

    let metadata: OutpostSignatureMetadata = {
      version: PROTOCOL_VERSION,
      outpost_id: OUTPOST_ID,
      timestamp,
      request_id: requestId,
      service: SERVICE,
      signed_headers: signedHeaders.map(h => h.name),
      signature,
      ...overrides.metadataOverrides
    };

    let headers: Record<string, string> = {};
    if (!overrides.omitOutpostIdHeader) headers[OUTPOST_ID_HEADER] = OUTPOST_ID;
    if (!overrides.omitSignatureHeader) {
      headers[OUTPOST_SIGNATURE_HEADER] = encodeSignatureHeader(metadata);
    }
    if (!overrides.omitInstanceTokenHeader) {
      headers[OUTPOST_INSTANCE_TOKEN_HEADER] =
        overrides.instanceTokenOverride ?? instanceToken;
    }

    Object.assign(headers, overrides.forwardedHeaders);

    return new Request(`http://localhost${path}`, {
      method,
      headers,
      body: body || undefined
    });
  };

  let buildApp = (resolver?: {
    resolveInstanceAuthorization?: (input: any) => Promise<ResolvedInstanceAuthorization>;
    resolveEnrollmentCredential?: (input: any) => Promise<ResolvedEnrollmentCredential>;
  }) => {
    let app = new Hono();
    app.onError((error, c) => {
      if (error instanceof OutpostServerError) {
        return c.json({ error: error.code }, { status: error.status as any });
      }
      return c.json({ error: 'internal_server_error' }, 500);
    });
    let options = {
      tokens,
      service: SERVICE,
      resolver: resolver
        ? {
            resolveInstanceAuthorization:
              [REDACTED] ??
              (async (): Promise<ResolvedInstanceAuthorization> => ({ status: 'active' })),
            resolveEnrollmentCredential:
              resolver.resolveEnrollmentCredential ?? defaultResolveEnrollmentCredential
          }
        : undefined
    } as any;
    app.get('/test', authenticateOutpostRequest(options), c =>
      c.json({ auth: c.get('outpostAuth') })
    );
    app.post('/test', authenticateOutpostRequest(options), c =>
      c.json({ auth: c.get('outpostAuth') })
    );
    return app;
  };

  it('authenticates a validly signed request', async () => {
    let app = buildApp();
    let res = await app.request(await buildRequest());

    expect(res.status).toBe(200);
    let body = await res.json();
    expect(body.auth.outpostId).toBe(OUTPOST_ID);
    expect(body.auth.instanceId).toBe(INSTANCE_ID);
    expect(body.auth.credentialId).toBe(CREDENTIAL_ID);
    expect(body.auth.service).toBe(SERVICE);
    expect(body.auth.outpostChain).toEqual([]);
  });

  it(
    'authenticates a request signed against its public https URL even though this ' +
      'process only ever sees plain HTTP behind a TLS-terminating proxy',
    async () => {
      let app = buildApp();
      let res = await app.request(
        await buildRequest({
          scheme: 'https',
          authority: 'api.metorial-staging.com',
          forwardedHeaders: {
            'x-forwarded-proto': 'https',
            'x-forwarded-host': 'api.metorial-staging.com'
          }
        })
      );

      expect(res.status).toBe(200);
    }
  );

  it('rejects a request whose signed scheme/authority do not match X-Forwarded-*', async () => {
    let app = buildApp();
    let res = await app.request(
      await buildRequest({
        scheme: 'https',
        authority: 'api.metorial-staging.com',
        forwardedHeaders: { 'x-forwarded-proto': 'http' }
      })
    );

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('invalid_signature');
  });

  it('rejects a request missing the Metorial-Outpost-Id header', async () => {
    let app = buildApp();
    let res = await app.request(await buildRequest({ omitOutpostIdHeader: true }));

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('missing_authentication');
  });

  it('rejects a request missing the Metorial-Outpost-Signature header', async () => {
    let app = buildApp();
    let res = await app.request(await buildRequest({ omitSignatureHeader: true }));

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('missing_authentication');
  });

  it('rejects a request missing the Metorial-Outpost-Instance-Token header', async () => {
    let app = buildApp();
    let res = await app.request(await buildRequest({ omitInstanceTokenHeader: true }));

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('missing_authentication');
  });

  it('rejects malformed signature metadata', async () => {
    let app = buildApp();
    let req = new Request('http://localhost/test', {
      headers: {
        [OUTPOST_ID_HEADER]: OUTPOST_ID,
        [OUTPOST_INSTANCE_TOKEN_HEADER]: instanceToken,
        [OUTPOST_SIGNATURE_HEADER]: 'not-base64url-json'
      }
    });

    let res = await app.request(req);
    expect(res.status).toBe(400);
    expect((await res.json()).error).toBe('malformed_signature_header');
  });

  it('rejects an unsupported version', async () => {
    let app = buildApp();
    let res = await app.request(await buildRequest({ metadataOverrides: { version: 2 } }));

    expect(res.status).toBe(400);
    expect((await res.json()).error).toBe('unsupported_version');
  });

  it('rejects an invalid instance token', async () => {
    let app = buildApp();
    let res = await app.request(
      await buildRequest({ instanceTokenOverride: 'garbage.v1.data.sig' })
    );

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('invalid_instance_token');
  });

  it('rejects an instance token signed by an unknown issuer key', async () => {
    let otherIssuer = await Ed25519.generateKeyPair();
    let otherTokens = new OutpostTokens({
      signing: {
        kid: 'mik_other',
        privateKey: [REDACTED],
        publicKey: otherIssuer.publicKey
      }
    });
    let foreignToken = await otherTokens.sign({
      type: INSTANCE_TOKEN_TYPE,
      data: {
        outpost_id: OUTPOST_ID,
        instance_id: INSTANCE_ID,
        instance_public_key: base64url.encode(
          await Ed25519.exportPublicKey(instance.publicKey)
        )
      }
    });

    let app = buildApp();
    let res = await app.request(await buildRequest({ instanceTokenOverride: foreignToken }));

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('invalid_instance_token');
  });

  it('rejects a header outpost_id that does not match the signed metadata', async () => {
    let app = buildApp();
    let req = await buildRequest();
    let mismatched = new Request(req, { headers: req.headers });
    mismatched.headers.set(OUTPOST_ID_HEADER, 'otp_other');

    let res = await app.request(mismatched);
    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('outpost_mismatch');
  });

  it('rejects a service mismatch', async () => {
    let app = buildApp();
    let res = await app.request(
      await buildRequest({ metadataOverrides: { service: 'metorial.other' } })
    );

    expect(res.status).toBe(403);
    expect((await res.json()).error).toBe('service_mismatch');
  });

  it('rejects a stale request', async () => {
    let app = buildApp();
    let res = await app.request(
      await buildRequest({
        metadataOverrides: { timestamp: Math.floor(Date.now() / 1000) - 3600 }
      })
    );

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('stale_request');
  });

  it('rejects a future-dated request', async () => {
    let app = buildApp();
    let res = await app.request(
      await buildRequest({
        metadataOverrides: { timestamp: Math.floor(Date.now() / 1000) + 3600 }
      })
    );

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('future_request');
  });

  it('rejects a request with a required header present but not signed', async () => {
    let app = buildApp();
    let req = await buildRequest();
    let withUnsigned = new Request(req, { headers: req.headers });
    withUnsigned.headers.set('authorization', 'Bearer sneaky');

    let res = await app.request(withUnsigned);
    expect(res.status).toBe(400);
    expect((await res.json()).error).toBe('missing_required_signed_header');
  });

  it('rejects an invalid signature', async () => {
    let otherInstance = await Ed25519.generateKeyPair();
    let app = buildApp();
    let res = await app.request(
      await buildRequest({ signWithInstanceKey: otherInstance.privateKey })
    );

    expect(res.status).toBe(401);
    expect((await res.json()).error).toBe('invalid_signature');
  });

  describe('authorization state (spec §42 Step 5)', () => {
    it('skips the check entirely when no resolver is supplied', async () => {
      let app = buildApp();
      let res = await app.request(await buildRequest());
      expect(res.status).toBe(200);
    });

    it('passes a request when the resolver reports the instance active', async () => {
      let resolveInstanceAuthorization = async (): Promise<ResolvedInstanceAuthorization> => ({
        status: 'active'
      });
      let app = buildApp({ resolveInstanceAuthorization });
      let res = await app.request(await buildRequest());
      expect(res.status).toBe(200);
    });

    it('passes the resolver the outpost/instance/credential ids from the token', async () => {
      let seen: any;
      let resolver = {
        resolveInstanceAuthorization: async (
          input: any
        ): Promise<ResolvedInstanceAuthorization> => {
          seen = input;
          return { status: 'active' };
        }
      };
      let app = buildApp(resolver);
      await app.request(await buildRequest());

      expect(seen).toEqual({
        outpostId: OUTPOST_ID,
        instanceId: INSTANCE_ID,
        credentialId: CREDENTIAL_ID
      });
    });

    it('rejects when the resolver reports the instance disabled', async () => {
      let resolveInstanceAuthorization = async (): Promise<ResolvedInstanceAuthorization> => ({
        status: 'instance_disabled'
      });
      let app = buildApp({ resolveInstanceAuthorization });
      let res = await app.request(await buildRequest());

      expect(res.status).toBe(403);
      expect((await res.json()).error).toBe('instance_disabled');
    });

    it('rejects when the resolver reports the outpost disabled', async () => {
      let resolveInstanceAuthorization = async (): Promise<ResolvedInstanceAuthorization> => ({
        status: 'outpost_disabled'
      });
      let app = buildApp({ resolveInstanceAuthorization });
      let res = await app.request(await buildRequest());

      expect(res.status).toBe(403);
      expect((await res.json()).error).toBe('outpost_disabled');
    });

    it('rejects an unknown instance/credential/outpost combination as an invalid token', async () => {
      let resolveInstanceAuthorization = async (): Promise<ResolvedInstanceAuthorization> => ({
        status: 'unknown'
      });
      let app = buildApp({ resolveInstanceAuthorization });
      let res = await app.request(await buildRequest());

      expect(res.status).toBe(401);
      expect((await res.json()).error).toBe('invalid_instance_token');
    });
  });

  describe('credential co-signature re-verification', () => {
    it('passes when the embedded credential-signed instance id still verifies', async () => {
      let app = buildApp({});
      let res = await app.request(await buildRequest());
      expect(res.status).toBe(200);
    });

    it('rejects once the enrollment credential is reported revoked', async () => {
      let app = buildApp({
        resolveEnrollmentCredential: async (): Promise<ResolvedEnrollmentCredential> => ({
          status: 'revoked'
        })
      });
      let res = await app.request(await buildRequest());

      expect(res.status).toBe(403);
      expect((await res.json()).error).toBe('revoked_outpost_credential');
    });

    it('rejects once the enrollment credential is reported unknown', async () => {
      let app = buildApp({
        resolveEnrollmentCredential: async (): Promise<ResolvedEnrollmentCredential> => ({
          status: 'unknown'
        })
      });
      let res = await app.request(await buildRequest());

      expect(res.status).toBe(404);
      expect((await res.json()).error).toBe('unknown_outpost_credential');
    });

    it('rejects a token whose embedded credential signature does not verify against the current credential key', async () => {
      let otherEnrollment = await Ed25519.generateKeyPair();
      let app = buildApp({
        resolveEnrollmentCredential: async (): Promise<ResolvedEnrollmentCredential> => ({
          status: 'ok',
          publicKey: await Ed25519.exportPublicKey(otherEnrollment.publicKey)
        })
      });
      let res = await app.request(await buildRequest());

      expect(res.status).toBe(401);
      expect((await res.json()).error).toBe('invalid_credential_signature');
    });

    it('rejects a token missing the embedded credential signature', async () => {
      let tokenWithoutCredentialSignature = await tokens.sign({
        type: INSTANCE_TOKEN_TYPE,
        data: {
          outpost_id: OUTPOST_ID,
          instance_id: INSTANCE_ID,
          credential_id: CREDENTIAL_ID,
          instance_public_key: base64url.encode(
            await Ed25519.exportPublicKey(instance.publicKey)
          )
        }
      });

      let app = buildApp({});
      let res = await app.request(
        await buildRequest({ instanceTokenOverride: tokenWithoutCredentialSignature })
      );

      expect(res.status).toBe(401);
      expect((await res.json()).error).toBe('invalid_credential_signature');
    });

    it('still verifies against the credential key when registration is currently disabled', async () => {
      let app = buildApp({
        resolveEnrollmentCredential: async (): Promise<ResolvedEnrollmentCredential> => ({
          status: 'registration_disabled',
          publicKey: enrollmentPublicKeyBytes
        })
      });
      let res = await app.request(await buildRequest());

      expect(res.status).toBe(200);
    });
  });

  it('round-trips outpost_chain and proxy_context into the authenticated result', async () => {
    let app = new Hono();
    app.onError((error, c) => {
      if (error instanceof OutpostServerError) {
        return c.json({ error: error.code }, { status: error.status as any });
      }
      return c.json({ error: 'internal_server_error' }, 500);
    });
    app.get('/test', async c => {
      let authed = await verifyOutpostRequest({ tokens, service: SERVICE }, c);
      return c.json({ authed });
    });

    let timestamp = Math.floor(Date.now() / 1000);
    let requestId = generateRequestId();
    let signedHeaders = canonicalizeSignedHeaders({}, []);
    let outpostChain: [string, string][] = [
      ['otp_a', 'oti_a'],
      ['otp_b', 'oti_b']
    ];
    let proxyContext = { ip: '1.2.3.4', user_agent: 'test-agent' };

    let signature = await signRequest(instance.privateKey, {
      version: PROTOCOL_VERSION,
      outpostId: OUTPOST_ID,
      instanceId: INSTANCE_ID,
      timestamp,
      requestId,
      service: SERVICE,
      method: 'GET',
      scheme: 'http',
      authority: 'localhost',
      path: '/test',
      query: '',
      signedHeaders,
      bodySha256: await hashBody(new Uint8Array(0)),
      outpostChain,
      proxyContext
    });

    let metadata: OutpostSignatureMetadata = {
      version: PROTOCOL_VERSION,
      outpost_id: OUTPOST_ID,
      timestamp,
      request_id: requestId,
      service: SERVICE,
      signed_headers: [],
      signature,
      outpost_chain: outpostChain,
      proxy_context: proxyContext
    };

    let res = await app.request(
      new Request('http://localhost/test', {
        headers: {
          [OUTPOST_ID_HEADER]: OUTPOST_ID,
          [OUTPOST_INSTANCE_TOKEN_HEADER]: instanceToken,
          [OUTPOST_SIGNATURE_HEADER]: encodeSignatureHeader(metadata)
        }
      })
    );

    expect(res.status).toBe(200);
    let body = await res.json();
    expect(body.authed.outpostChain).toEqual(outpostChain);
    expect(body.authed.proxyContext).toEqual(proxyContext);
  });
});

import {
  encodeCredentialEnvelope,
  type OutpostCredential
} from '@metorial-outpost/credential-envelope';
import { base64url, Ed25519, sha256 } from '@metorial-outpost/crypto';
import {
  decodeSignatureHeader,
  OUTPOST_ID_HEADER,
  OUTPOST_INSTANCE_TOKEN_HEADER,
  OUTPOST_SIGNATURE_HEADER,
  verifyRequestSignature,
  type RequestSignatureInput
} from '@metorial-outpost/signature';
import { describe, expect, it, vi } from 'vitest';
import { OutpostAuth } from './outpost-auth';
import { MemoryInstanceCredentialStore } from './stores/memory';

let jsonResponse = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json' }
  });

let buildCredential = async (): Promise<{
  credential: OutpostCredential;
  envelope: string;
  outpostKeyPair: CryptoKeyPair;
}> => {
  let outpostKeyPair = (await Ed25519.generateKeyPair()) as unknown as CryptoKeyPair;

  let credential: OutpostCredential = {
    version: 1,
    endpoint: 'https://outpost.metorial.com',
    outpost_id: 'otp_123',
    credential_id: 'otc_456',
    private_key: [REDACTED]
      await Ed25519.exportPrivateKey(outpostKeyPair.privateKey as CryptoKey)
    )
  };

  return { outpostKeyPair, credential, envelope: encodeCredentialEnvelope(credential) };
};

let registrationFetchMock = () =>
  vi.fn(async (url: string) => {
    if (url.endsWith('/outpost/register/challenge')) {
      return jsonResponse({
        challenge_id: 'och_123',
        challenge: base64url.encode(crypto.getRandomValues(new Uint8Array(32)))
      });
    }

    if (url.endsWith('/outpost/register')) {
      return jsonResponse({ instance_token: '[REDACTED]' });
    }

    throw new Error(`Unexpected URL: ${url}`);
  });

describe('OutpostAuth', () => {
  it('registers lazily, only once, even under concurrent sign() calls', async () => {
    let { envelope } = await buildCredential();
    let fetchMock = registrationFetchMock();

    let auth = new OutpostAuth({
      credential: envelope,
      defaultService: 'metorial.proxy',
      fetch: fetchMock as unknown as typeof fetch
    });

    let [first, second] = await Promise.all([
      auth.sign({ method: 'GET', url: 'https://api.metorial.com/v1/foo' }),
      auth.sign({ method: 'GET', url: 'https://api.metorial.com/v1/bar' })
    ]);

    expect(fetchMock).toHaveBeenCalledTimes(2); // one challenge call, one register call
    expect(first[OUTPOST_ID_HEADER]).toBe('otp_123');
    expect(second[OUTPOST_ID_HEADER]).toBe('otp_123');
  });

  it('produces a request signature that verifies against the stored instance credentials', async () => {
    let { credential, envelope } = await buildCredential();
    let store = new MemoryInstanceCredentialStore();
    let fetchMock = registrationFetchMock();

    let auth = new OutpostAuth({
      credential: envelope,
      store,
      fetch: fetchMock as unknown as typeof fetch
    });

    let body = JSON.stringify({ hello: 'world' });
    let headers = { authorization: 'Bearer abc', 'content-type': 'application/json' };

    let signed = await auth.sign({
      method: 'POST',
      url: 'https://api.metorial.com/v1/foo?a=1',
      service: 'metorial.proxy',
      headers,
      body
    });

    let metadata = decodeSignatureHeader(signed[OUTPOST_SIGNATURE_HEADER]!);
    expect(signed[OUTPOST_INSTANCE_TOKEN_HEADER]).toBe('instance-token-value');
    expect(metadata.service).toBe('metorial.proxy');
    expect(metadata.signed_headers).toEqual(['authorization', 'content-type']);

    let credentials = await store.load();
    expect(credentials).not.toBeNull();

    let instancePublicKey = await Ed25519.importPublicKey(
      base64url.decode(credentials!.instancePublicKey)
    );

    let signatureInput: RequestSignatureInput = {
      outpostId: credential.outpost_id,
      instanceId: credentials!.instanceId,
      timestamp: metadata.timestamp,
      requestId: metadata.request_id,
      service: metadata.service,
      method: 'POST',
      scheme: 'https',
      authority: 'api.metorial.com',
      path: '/v1/foo',
      query: 'a=1',
      signedHeaders: [
        { name: 'authorization', value: 'Bearer abc' },
        { name: 'content-type', value: 'application/json' }
      ],
      bodySha256: await sha256(new TextEncoder().encode(body))
    };

    expect(
      await verifyRequestSignature(instancePublicKey, signatureInput, metadata.signature)
    ).toBe(true);
  });

  it('never calls the network when the store already holds instance credentials', async () => {
    let { envelope } = await buildCredential();
    let instance = await Ed25519.generateKeyPair();

    let store = new MemoryInstanceCredentialStore({
      instanceId: 'oti_existing',
      instancePrivateKey: [REDACTED]
        await Ed25519.exportPrivateKey(instance.privateKey)
      ),
      instancePublicKey: base64url.encode(await Ed25519.exportPublicKey(instance.publicKey)),
      instanceToken: '[REDACTED]'
    });

    let fetchMock = vi.fn(() => {
      throw new Error('should not be called');
    });

    let auth = new OutpostAuth({
      credential: envelope,
      store,
      defaultService: 'metorial.proxy',
      fetch: fetchMock as unknown as typeof fetch
    });

    let signed = await auth.sign({ method: 'GET', url: 'https://api.metorial.com/v1/foo' });

    expect(fetchMock).not.toHaveBeenCalled();
    expect(signed[OUTPOST_INSTANCE_TOKEN_HEADER]).toBe('existing-token');
  });

  it('throws when sign() is called without a service and no default is configured', async () => {
    let { envelope } = await buildCredential();
    let auth = new OutpostAuth({
      credential: envelope,
      store: new MemoryInstanceCredentialStore({
        instanceId: 'oti_existing',
        instancePrivateKey: 'irrelevant',
        instancePublicKey: 'irrelevant',
        instanceToken: 'irrelevant'
      })
    });

    await expect(
      auth.sign({ method: 'GET', url: 'https://api.metorial.com/v1/foo' })
    ).rejects.toThrow(/service/);
  });

  it('retries registration after a failed attempt instead of caching the rejection', async () => {
    let { envelope } = await buildCredential();
    let attempt = 0;

    let fetchMock = vi.fn(async (url: string) => {
      if (url.endsWith('/outpost/register/challenge')) {
        attempt++;
        if (attempt == 1) return jsonResponse({ error: 'try again' }, 500);
        return jsonResponse({
          challenge_id: 'och_123',
          challenge: base64url.encode(crypto.getRandomValues(new Uint8Array(32)))
        });
      }

      return jsonResponse({ instance_token: '[REDACTED]' });
    });

    let auth = new OutpostAuth({
      credential: envelope,
      defaultService: 'metorial.proxy',
      fetch: fetchMock as unknown as typeof fetch
    });

    await expect(
      auth.sign({ method: 'GET', url: 'https://api.metorial.com/v1/foo' })
    ).rejects.toThrow();

    let signed = await auth.sign({ method: 'GET', url: 'https://api.metorial.com/v1/foo' });
    expect(signed[OUTPOST_ID_HEADER]).toBe('otp_123');
  });

  describe('getSnapshot', () => {
    it('reports the outpost/credential ids and endpoint before any registration happens', async () => {
      let { envelope } = await buildCredential();
      let auth = new OutpostAuth({ credential: envelope });

      expect(auth.getSnapshot()).toEqual({
        outpostId: 'otp_123',
        credentialId: 'otc_456',
        endpoint: 'https://outpost.metorial.com',
        instanceId: undefined,
        registered: false,
        tokenExpiresAt: null
      });
    });

    it('includes the instance id and token expiry once registered, without leaking secrets', async () => {
      let { envelope } = await buildCredential();
      let fetchMock = registrationFetchMock();

      let auth = new OutpostAuth({
        credential: envelope,
        defaultService: 'metorial.proxy',
        upstreamUrl: 'https://parent.outpost.example',
        fetch: fetchMock as unknown as typeof fetch
      });

      await auth.sign({ method: 'GET', url: 'https://api.metorial.com/v1/foo' });

      let snapshot = auth.getSnapshot();
      expect(snapshot.registered).toBe(true);
      expect(snapshot.endpoint).toBe('https://parent.outpost.example');
      expect(typeof snapshot.instanceId).toBe('string');
      expect(JSON.stringify(snapshot)).not.toContain('instance-token-value');
      expect(JSON.stringify(snapshot)).not.toMatch(/private/i);
    });
  });
});

import { describe, expect, it } from 'vitest';
import { MemoryInstanceCredentialStore } from './memory';

let credentials = {
  instanceId: 'oti_123',
  instancePrivateKey: 'priv',
  instancePublicKey: 'pub',
  instanceToken: 'token'
};

describe('MemoryInstanceCredentialStore', () => {
  it('starts empty', async () => {
    let store = new MemoryInstanceCredentialStore();
    expect(await store.load()).toBeNull();
  });

  it('can be seeded with initial credentials', async () => {
    let store = new MemoryInstanceCredentialStore(credentials);
    expect(await store.load()).toEqual(credentials);
  });

  it('round-trips saved credentials', async () => {
    let store = new MemoryInstanceCredentialStore();
    await store.save(credentials);
